import {getOS} from './index'
// for all
export async function initBridge() {
  const os = getOS()
  console.log('os',os)
  if(os && os > 0) {
    await initIosBridge()
  }
  if(os && os < 1) {
    initAndroidBridge()
  }
}
export async function callApp(methodName:any, data:any) {
  const os = getOS()
  console.log('os',os)
  if(os && os > 0) {
    callIos(methodName, data)
  }
  if(os && os < 1) {
    callAndroid(methodName, data)
  }
}

// for ios
// ios js bridge 注入方法
export function setupWKWebViewJavascriptBridge(callback:any) {
  let w = window
  if (w.WKWebViewJavascriptBridge) { return callback(w.WKWebViewJavascriptBridge) }
  if (w.WKWVJBCallbacks) { return w.WKWVJBCallbacks.push(callback) }
  w.WKWVJBCallbacks = [callback]
  w?.webkit?.messageHandlers?.iOS_Native_InjectJavascript?.postMessage?.(null)
}
// ios js bridge init
export function initIosBridge() {
  console.log('init ios bridge start')
  return new Promise((resolve, reject) => {
    setupWKWebViewJavascriptBridge((bridge:any) => {
      console.log('bridge', bridge)
      resolve(bridge)
    })
  })
}
export function callIos(methodName:any, data:any) {
  return new Promise((resolve) => {
    let w = window
    if (w.WKWebViewJavascriptBridge) {
      try {
        console.log('iosJSAPI', { method: methodName, data: data })
        w.WKWebViewJavascriptBridge.callHandler('iosJSAPI', {
          method: methodName,
          data: data
        }, function responseCallback(responseData:any) {
          resolve(responseData)
          console.log('JS received response:', responseData)
        })
      } catch (err) {
        resolve(null)
      }
    } else if (w?.webkit?.messageHandlers?.iOS_Native_InjectJavascript) {
      setupWKWebViewJavascriptBridge((bridge:any) => {
        if (bridge) {
          try {
            console.log('iosJSAPI', { method: methodName, data: data })
            bridge.callHandler('iosJSAPI', {
              method: methodName,
              data: data
            }, function responseCallback(responseData:any) {
              resolve(responseData)
              console.log('JS received response:', responseData)
            })
          } catch (err) {
            resolve(null)
          }
        } else {
          resolve(null)
        }
      })
    } else {
      resolve(null)
    }
  })
}

// for Android
function connectWebViewJavascriptBridge(callback:any) {
  let w = window
  if (w.WebViewJavascriptBridge) {
    callback(w.WebViewJavascriptBridge)
  } else {
    document.addEventListener('WebViewJavascriptBridgeReady', function() {callback(w.WebViewJavascriptBridge)}, false)
  }
}

function getAndroidBridge(callback:any) {
  let w = window
  if (w.WebViewJavascriptBridge) {
    callback(w.WebViewJavascriptBridge)
  } else {
    setTimeout(() => {
      if (w.WebViewJavascriptBridge) {
        callback(w.WebViewJavascriptBridge)
      } else {
        callback(null)
      }
    }, 3000)
  }
}

function isJSON(str:any) {
  if (typeof str == 'string') {
    try {
      var obj = JSON.parse(str)
      if (typeof obj == 'object' && obj) {
        return true
      } else {
        return false
      }
    } catch (e) {
      return false
    }
  }
  return false
}

export function initAndroidBridge() {
  console.log('init android bridge start')
  connectWebViewJavascriptBridge(function(bridge:any) {
    bridge.init(function(message:any, responseCallback:any) {
      console.log('JS got a message', message)
      var data = {
        'Javascript Responds': '测试!'
      }
      console.log('JS responding with', data)
      responseCallback(data)
    })
    // registerBridgeMethod(bridge)
  })
}

export function callAndroid(methodName:any, data:any) {
  return new Promise((resolve, reject) => {
    let w = window
    if (w.WebViewJavascriptBridge) {
      try {
        let bridge = w.WebViewJavascriptBridge
        console.log('bridge.callHandler', methodName, data)
        bridge.callHandler(methodName, data, function(responseData) {
          console.log('JS received response:', responseData)
          if (responseData && typeof responseData === 'string' && isJSON(responseData)) {
            responseData = JSON.parse(responseData)
          }
          if (responseData?.isError && responseData?.message) {
            reject(responseData?.message)
          } else {
            resolve(responseData)
          }
        })
      } catch(err) {
        reject(err)
      }
    } else {
      getAndroidBridge((bridge:any) => {
        if (bridge) {
          try {
            console.log('bridge.callHandler', methodName, data)
            bridge.callHandler(methodName, data, function(responseData:any) {
              console.log('JS received response:', responseData)
              if (responseData && typeof responseData === 'string' && isJSON(responseData)) {
                responseData = JSON.parse(responseData)
              }
              if (responseData?.isError && responseData?.message) {
                reject(responseData?.message)
              } else {
                resolve(responseData)
              }
            })
          } catch(err) {
            reject(err)
          }
        } else {
          reject('WebViewJavascriptBridge is null')
        }
      })
    }
  })
}